// Valider et preparer les parametres PDF
const input = $input.first().json;
const body = input.body || input;

// Configuration par defaut
const defaultConfig = {
  format: 'bilingual',
  page_size: 'A4',
  include_commentaries: true,
  include_source: true,
  include_translation: true,
  font_size: 12,
  rtl_support: true,
  max_commentaries_per_page: 5,
  output_format: 'pdf'
};

const config = { ...defaultConfig, ...body.config };

// Validation
const errors = [];
if (!body.book && !body.translation_ids) {
  errors.push('Specify either "book" (e.g., "Sukkah") or "translation_ids" array');
}

const validFormats = ['bilingual', 'source_only', 'translation_only', 'academic', 'annotated'];
if (!validFormats.includes(config.format)) {
  errors.push(`Invalid format. Use: ${validFormats.join(', ')}`);
}

const result = {
  valid: errors.length === 0,
  errors: errors,
  params: {
    book: body.book || null,
    chapter_start: body.chapter_start || '2a',
    chapter_end: body.chapter_end || null,
    translation_ids: body.translation_ids || [],
    config: config,
    job_id: `pdf_${Date.now()}`
  }
};

return [{ json: result }];

