// Preparer les donnees pour la generation PDF
const apiResponse = $input.first().json;
const params = $('Validate PDF Parameters').first().json.params;

// Extraire les traductions
let translations = [];
if (apiResponse.items) {
  translations = apiResponse.items;
} else if (apiResponse.translations) {
  translations = apiResponse.translations;
} else if (Array.isArray(apiResponse)) {
  translations = apiResponse;
}

// Filtrer par plage de chapitres si specifie
if (params.chapter_start || params.chapter_end) {
  const parseRef = (ref) => {
    const match = (ref || '').match(/(\d+)([ab])/i);
    if (!match) return { num: 0, side: 'a' };
    return { num: parseInt(match[1]), side: match[2].toLowerCase() };
  };

  const start = params.chapter_start ? parseRef(params.chapter_start) : { num: 0, side: 'a' };
  const end = params.chapter_end ? parseRef(params.chapter_end) : { num: 999, side: 'b' };

  translations = translations.filter(t => {
    const ref = parseRef(t.reference || t.ref || '');
    const startVal = start.num * 2 + (start.side === 'b' ? 1 : 0);
    const endVal = end.num * 2 + (end.side === 'b' ? 1 : 0);
    const refVal = ref.num * 2 + (ref.side === 'b' ? 1 : 0);
    return refVal >= startVal && refVal <= endVal;
  });
}

// Trier par reference
translations.sort((a, b) => {
  const refA = (a.reference || '').match(/(\d+)([ab])/i) || [0, 0, 'a'];
  const refB = (b.reference || '').match(/(\d+)([ab])/i) || [0, 0, 'a'];
  const numA = parseInt(refA[1]) * 2 + (refA[2] === 'b' ? 1 : 0);
  const numB = parseInt(refB[1]) * 2 + (refB[2] === 'b' ? 1 : 0);
  return numA - numB;
});

if (translations.length === 0) {
  return [{ json: { error: 'Aucune traduction approuvee trouvee', translations_count: 0 } }];
}

return [{
  json: {
    translations_count: translations.length,
    translation_ids: translations.map(t => t.uuid || t.id),
    references: translations.map(t => t.reference),
    job_id: params.job_id,
    config: params.config,
    book: params.book
  }
}];

// Traiter le resultat de generation PDF
const input = $input.first().json;
const pdfData = $('Prepare PDF Data').first().json;

const result = {
  success: !input.error && !input.detail && (input.pdf_url || input.file_path),
  job_id: pdfData.job_id,
  pdf_url: input.pdf_url || null,
  file_path: input.file_path || null,
  file_size: input.file_size || null,
  pages: input.pages || null,
  translations_included: pdfData.translations_count,
  error: input.error || input.detail || null,
  generated_at: new Date().toISOString()
};

// Construire l'URL de telechargement
if (result.file_path && !result.pdf_url) {
  result.pdf_url = `http://pi6.local:3031/api/pdf/download/${pdfData.job_id}`;
}

return [{ json: result }];

